'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),crypto=require('node:crypto');
const {fixtures}=require('./fixtures/phase1f-compatibility-fixtures');const bundlePath=path.resolve(__dirname,'../preview-only/assignment-v2-preview.bundle.js');
test('preview bundle is browser-consumable and exposes only the intended surface',()=>{const source=fs.readFileSync(bundlePath,'utf8'),context={};vm.createContext(context);vm.runInContext(source,context);const api=context.SmartHSRAssignmentV2PreviewBundle;assert.ok(api);assert.deepEqual(Object.keys(api).sort(),['evaluatePreviewCompatibility','getAssignmentV2PreviewApi','getAssignmentV2PreviewStatus','initializeAssignmentV2Preview','isAssignmentV2PreviewAvailable']);});
test('bundle contains no Node APIs, source maps, secrets, or Production project id',()=>{const source=fs.readFileSync(bundlePath,'utf8');for(const pattern of [/require\(['"]node:/,/sourceMappingURL/i,/apiKey/i,/private_key/i,/client_email/i,/smart-hsr-manager/i])assert.doesNotMatch(source,pattern);});
test('bundle hash is a stable SHA-256 value',()=>{const hash=crypto.createHash('sha256').update(fs.readFileSync(bundlePath)).digest('hex');assert.match(hash,/^[a-f0-9]{64}$/);});
test('40-fixture bundle compatibility gate allows 26 and denies 14',()=>{const source=fs.readFileSync(bundlePath,'utf8'),context={};vm.createContext(context);vm.runInContext(source,context);const gate=context.SmartHSRAssignmentV2PreviewBundle.evaluatePreviewCompatibility;const decisions=fixtures.map(value=>gate(value));assert.equal(decisions.filter(x=>x.allowed).length,26);assert.equal(decisions.filter(x=>!x.allowed).length,14);for(const item of decisions.filter(x=>['ambiguous','invalid'].includes(x.classification)))assert.equal(item.allowed,false);});
